func sptFill(b *port.Bitmap, r int32, g int32, bl int32) int32 {
	var x int32 = 0
	var y int32 = 0
	for y < port.BitmapH(b) {
		x = 0
		for x < port.BitmapW(b) {
			port.BitmapSetU8(b, x, y, 0, r)
			port.BitmapSetU8(b, x, y, 1, g)
			port.BitmapSetU8(b, x, y, 2, bl)
			x += 1
		}
		y += 1
	}
	return 0
}

func sptBlock(b *port.Bitmap, x0 int32, y0 int32, w int32, h int32, r int32, g int32, bl int32) int32 {
	var x int32 = 0
	var y int32 = 0
	for y < h {
		x = 0
		for x < w {
			port.BitmapSetU8(b, x0+x, y0+y, 0, r)
			port.BitmapSetU8(b, x0+x, y0+y, 1, g)
			port.BitmapSetU8(b, x0+x, y0+y, 2, bl)
			x += 1
		}
		y += 1
	}
	return 0
}

func TestAPixelIsTheInksByItsPlaceOnThePaperToInkLine(emonT *testing.T) {
	var kp *port.Cells = port.NewCells()
	sealpx.SxKeySetup(kp, 2047903, 3)
	port.AssertEq(emonT, sealpx.SxKey(kp, 31, 63, 159), 255, "the ink itself (#1f3f9f) is all ink")
	port.AssertEq(emonT, sealpx.SxKey(kp, 255, 255, 255), 0, "paper is none")
	port.AssertEq(emonT, sealpx.SxKey(kp, 0, 0, 0), 0, "black body text is none: it is far from the line")
	port.AssertEq(emonT, sealpx.SxKey(kp, 200, 30, 30), 0, "a red is none")
	port.AssertThat(emonT, (sealpx.SxKey(kp, 143, 159, 207) > 80) && (sealpx.SxKey(kp, 143, 159, 207) < 112), "half way to the ink is under half: the least fifth is the paper's texture and is none")
	port.AssertEq(emonT, sealpx.SxKey(kp, 235, 240, 245), 0, "a paper's texture (a twelfth of the way) is none")
	port.AssertThat(emonT, sealpx.SxKey(kp, 0, 0, 100) > 180, "a darker blue than the ink is nearly all ink")
	port.AssertEq(emonT, sealpx.SxKey(kp, 90, 90, 90), 0, "a gray, dark as the ink, is none: a coloured ink is told by its chroma")
	sealpx.SxKeySetup(kp, 12591135, 3)
	port.AssertEq(emonT, sealpx.SxKey(kp, 192, 32, 31), 255, "a red ink (#c0201f) is all ink to a red key")
	port.AssertEq(emonT, sealpx.SxKey(kp, 31, 63, 159), 0, "and a blue is none")
	sealpx.SxKeySetup(kp, 16119285, 3)
	port.AssertEq(emonT, sealpx.SxKey(kp, 0, 0, 0), 255, "an ink as light as the paper is taken for a dark gray: black is all of it")
}

