	sptGblock(b, 10, 12, 30, 3)
	sptGblock(b, 0, 16, 40, 1)
	port.AssertEq(emonT, sealpx.SxEraseRows(b, 0, 20), 2, "the two rows that are all ink are painted: two rows (the one of 30 and the one of 40 per cent stay)")
	port.AssertEq(emonT, port.BitmapU8(b, 50, 4, 0), 255, "the line is gone")
	port.AssertEq(emonT, port.BitmapU8(b, 20, 13, 0), 0, "the text row stays")
