func sptPrim(prims *port.Cells, kind int32, cx int32, cy int32, rx int32, ry int32, ink int32, rgb int32, flags int32, stroke int32) int32 {
	var r int32 = evidence.PmNew(prims, 1, cx-rx, cy-ry, cx+rx, cy+ry, kind)
	evidence.PmSet(prims, r, evidence.PmfCx(), cx)
	evidence.PmSet(prims, r, evidence.PmfCy(), cy)
	evidence.PmSet(prims, r, evidence.PmfRx(), rx)
	evidence.PmSet(prims, r, evidence.PmfRy(), ry)
	evidence.PmSet(prims, r, evidence.PmfInk(), ink)
	evidence.PmSet(prims, r, evidence.PmfColor(), rgb)
	evidence.PmSet(prims, r, evidence.PmfConf(), 900)
	evidence.PmSet(prims, r, evidence.PmfFlags(), flags)
	evidence.PmSet(prims, r, evidence.PmfStroke(), stroke)
	return r
}

func sptInk(inks *port.Cells, role int32) int32 {
	var r int32 = evidence.IkNew(inks, 1, 0)
	evidence.IkSet(inks, r, evidence.IkfRole(), role)
	return r
}

func TestARingOrAStampOnTheRightLayerIsACandidate(emonT *testing.T) {
	var views *port.Cells = port.NewCells()
	var prims *port.Cells = port.NewCells()
	var inks *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	evidence.VwNew(views, 1, evidence.VkRender(), -1, -1, 3000, 3000, 7200, 0, -1, 0, 0, 0, 0, 0)
	sptInk(inks, evidence.IrBody())
	sptInk(inks, evidence.IrLight())
	sptInk(inks, evidence.IrColor())
	// a blue ring of radius 30 pt at (20 pt, 20 pt)... on the colour layer
	sptPrim(prims, evidence.PmRing(), 20000, 20000, 3000, 3000, 2, 2047903, 4, 200)
	port.AssertEq(emonT, sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 1, "a ring on a colour layer: a candidate")
	port.AssertEq(emonT, port.CellsAt(cand, 0), 1, "a seal")
	port.AssertEq(emonT, port.CellsAt(cand, 2), 200, "its centre x in pixels (72 dpi: one a point)")
	port.AssertEq(emonT, port.CellsAt(cand, 4), 30, "its radius")
	port.AssertEq(emonT, port.CellsAt(cand, 13), 10, "its colour code: blue")
	// the ring of the page's body layer is one only as a double ring
	sptPrim(prims, evidence.PmCircle(), 40000, 20000, 3000, 3000, 0, 1118481, 0, 200)
	port.AssertEq(emonT, sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 1, "a single circle on the body layer is a diagram's: still the one candidate")
	sptPrim(prims, evidence.PmRing(), 40000, 40000, 3000, 3000, 0, 1118481, 4, 200)
	port.AssertEq(emonT, sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 2, "a double ring on the body layer is a seal")
	port.AssertEq(emonT, port.CellsAt(cand, 13), 10, "(the colour one first)")
	port.AssertEq(emonT, port.CellsAt(cand, 29), 0, "the body one is black")
	// a ring on a light layer (a watermark), a small ring: neither; an oblong curve of the colour layer (a rotated stamp's outline) is a stamp
	sptPrim(prims, evidence.PmRing(), 20000, 60000, 3000, 3000, 1, 13487565, 4, 200)
	sptPrim(prims, evidence.PmRing(), 20000, 60000, 1000, 1000, 2, 2047903, 4, 200)
	sptPrim(prims, evidence.PmCurve(), 40000, 60000, 3000, 4500, 2, 2047903, 0, 200)
	port.AssertEq(emonT, sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 3, "the oblong curve is a stamp, the other two are no candidate")
	// a ring inside another, concentric: one candidate, the larger
	sptPrim(prims, evidence.PmRing(), 20000, 20000, 2600, 2600, 2, 2047903, 0, 200)
	port.AssertEq(emonT, sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 3, "an inner ring is the seal's, not another")
	// a stamp: an outlined rectangle on the colour layer
	sptPrim(prims, evidence.PmRect(), 30000, 70000, 5000, 2000, 2, 12591135, 1, 200)
	port.AssertEq(emonT, sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 4, "an outlined rectangle on the colour layer: a stamp")
	port.AssertEq(emonT, port.CellsAt(cand, 48), 2, "a stamp")
	port.AssertEq(emonT, port.CellsAt(cand, 52), 50, "half its width in pixels")
	port.AssertEq(emonT, port.CellsAt(cand, 53), 20, "half its height")
}

func TestAColourBandAcrossThePageIsNoStamp(emonT *testing.T) {
	var views *port.Cells = port.NewCells()
	var prims *port.Cells = port.NewCells()
	var inks *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	// D583 (smoke review A issue 16): an outlined colour rectangle most of the page's width (a heading's band holding its text) is not a stamp; the same size of rectangle
	// 100 pt wide is one
	evidence.VwNew(views, 1, evidence.VkRender(), -1, -1, 3000, 3000, 7200, 0, -1, 0, 0, 0, 0, 0)
	sptInk(inks, evidence.IrBody())
	sptInk(inks, evidence.IrLight())
	sptInk(inks, evidence.IrColor())
	sptPrim(prims, evidence.PmRect(), 30600, 70000, 25000, 1500, 2, 12591135, 1, 200)
	port.AssertEq(emonT, sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 0, "a band 500 pt wide on a page 612 pt wide: no candidate")
	sptPrim(prims, evidence.PmRect(), 30000, 40000, 5000, 2000, 2, 12591135, 1, 200)
	port.AssertEq(emonT, sealpx.SxFind(1, views, 0, prims, inks, 61200, 79200, cand), 1, "a 100 pt rectangle is a stamp")
}

