func TestALineWhollyInsideAKeptSealIsNotBodyText(emonT *testing.T) {
	var cand *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var ol *port.Cells = port.NewCells()
	var scr *port.Cells = port.NewCells()
	for port.CellsLen(cand) < 16 {
		port.CellsPush(cand, 0)
	}
	port.CellsSet(cand, 0, 1)
	port.CellsSet(cand, 8, 1000)
	port.CellsSet(cand, 9, 1000)
	port.CellsSet(cand, 10, 7000)
	port.CellsSet(cand, 11, 7000)
	port.CellsSet(cand, 15, -2)
	sptOword(ow, 4000, 4000)
	sptOword(ow, 4000, 4500)
	sptOword(ow, 30000, 4000)
	sptOword(ow, 30000, 30000)
	evidence.OlNew(ol, 1, 3700, 3800, 4300, 4200, 3700, 4200, 4300, 4200, 0, 0, 0, 1)
	evidence.OlNew(ol, 1, 3700, 4300, 30300, 4700, 3700, 4700, 30300, 4700, 0, 0, 1, 2)
	evidence.OlNew(ol, 1, 29700, 29800, 30300, 30200, 29700, 30200, 30300, 30200, 0, 0, 3, 1)
	for port.CellsLen(scr) < (scan.ScSelBase() + 8) {
		port.CellsPush(scr, 0)
	}
	port.CellsSet(scr, scan.ScSelBase(), 0)
	port.CellsSet(scr, scan.ScSelBase()+1, 1)
	port.CellsSet(scr, scan.ScSelBase()+2, 2)
	port.AssertEq(emonT, sealpx.SxDropLines(scr, 3, ol, ow, cand), 2, "the line in the ring is out; the line that runs from the ring across the page and the line elsewhere stay")
	port.AssertEq(emonT, port.CellsAt(scr, scan.ScSelBase()), 1, "the first left is the second line")
	port.AssertEq(emonT, port.CellsAt(scr, scan.ScSelBase()+1), 2, "then the third")
	port.CellsSet(cand, 15, -1)
	port.CellsSet(scr, scan.ScSelBase(), 0)
	port.CellsSet(scr, scan.ScSelBase()+1, 1)
	port.CellsSet(scr, scan.ScSelBase()+2, 2)
	port.AssertEq(emonT, sealpx.SxDropLines(scr, 3, ol, ow, cand), 3, "a candidate whose reading was not kept takes nothing out of the body")
}

